on conflict(version,quest_id) do update set town_id=excluded.town_id,difficulty=excluded.difficulty,display_name=excluded.display_name,display_order=excluded.display_order,duration_sec=excluded.duration_sec,vitality_cost=excluded.vitality_cost,user_exp=excluded.user_exp,cash_reward=0,reward_pool_id=excluded.reward_pool_id,unlock_condition=excluded.unlock_condition,is_production_enabled=true,daily_first_clear_cash=excluded.daily_first_clear_cash,enemy_pool_key=excluded.enemy_pool_key;
update public.quests q set name=m.display_name,duration_seconds=m.duration_sec,cost_vitality=m.vitality_cost,exp_reward=m.user_exp,cash_reward=0
from public.canonical_quest_master m where m.version='2026-08-30' and m.quest_id=q.id;

create or replace function public.canonical_quest_is_unlocked(p_user_id uuid,p_quest_id text) returns boolean language sql stable security definer set search_path=public as $$
 select case when m.unlock_condition='OPEN' then true when m.unlock_condition like 'FIRST_CLEAR:%' then exists(select 1 from public.user_quest_first_clears c where c.user_id=p_user_id and c.quest_id=substring(m.unlock_condition from 13)) else false end from public.canonical_quest_master m where m.version='2026-08-30' and m.quest_id=p_quest_id and m.is_production_enabled
$$;
create or replace function public.get_canonical_quest_progression() returns jsonb language sql stable security definer set search_path=public as $$
 select coalesce(jsonb_agg(jsonb_build_object('quest_id',m.quest_id,'unlock_condition',m.unlock_condition,'is_unlocked',public.canonical_quest_is_unlocked(auth.uid(),m.quest_id),'is_first_cleared',exists(select 1 from public.user_quest_first_clears c where c.user_id=auth.uid() and c.quest_id=m.quest_id),'enemy_tactic','BALANCED','enemy_member_count',case when m.difficulty='EASY' then 3 else 5 end,'enemy_members','[]'::jsonb,'recommended_level',case m.difficulty when 'EASY' then 5 when 'NORMAL' then 12 else 20 end,'enemy_attributes','[]'::jsonb) order by m.display_order),'[]'::jsonb) from public.canonical_quest_master m where m.version='2026-08-30' and m.is_production_enabled
$$;

create or replace function public.start_patrol(p_course_id text,p_character_id text) returns jsonb
language plpgsql security definer set search_path=public as $$
declare v_uid uuid:=auth.uid(); v_character text; v_q record; v_id uuid; v_active integer; v_vitality integer;
begin
 if v_uid is null then raise exception 'authentication required' using errcode='42501'; end if;
 select * into v_q from public.canonical_quest_master where version='2026-08-30' and quest_id=p_course_id and is_production_enabled;
 if not found then raise exception 'quest not found' using errcode='23503'; end if;
 if not public.canonical_quest_is_unlocked(v_uid,p_course_id) then raise exception 'quest is locked' using errcode='23514'; end if;
 select owned.character_id into v_character from public.user_characters owned where owned.user_id=v_uid and(owned.id::text=p_character_id or owned.character_id=p_character_id) order by(owned.id::text=p_character_id)desc limit 1;
 if v_character is null then raise exception 'character is not owned' using errcode='23503'; end if;
 select count(*) into v_active from public.user_patrols where user_id=v_uid and status<>'COMPLETED'; if v_active>=5 then raise exception 'all dispatch slots are occupied' using errcode='23514'; end if;
 if exists(select 1 from public.user_patrols where user_id=v_uid and character_id=v_character and status<>'COMPLETED') then raise exception 'character is already dispatched' using errcode='23505'; end if;
 perform public.sync_and_recover_vitality_and_pvp_points(v_uid); select vitality into v_vitality from public.users where id=v_uid for update;
 if coalesce(v_vitality,0)<v_q.vitality_cost then raise exception 'insufficient vitality' using errcode='23514'; end if;
 insert into public.user_patrols(user_id,course_id,character_id,started_at,expires_at,status,has_battle_event,battle_resolved) values(v_uid,p_course_id,v_character,now(),now()+v_q.duration_sec*interval '1 second','ONGOING',true,false) returning id into v_id;
 update public.users set vitality=vitality-v_q.vitality_cost,vitality_last_recovered_at=case when vitality>=100 then now() else vitality_last_recovered_at end where id=v_uid;
 return jsonb_build_object('status','success','patrol_id',v_id,'has_battle',true,'duration_seconds',v_q.duration_sec,'cost_vitality',v_q.vitality_cost,'remaining_vitality',v_vitality-v_q.vitality_cost);
end $$;

create or replace function public.claim_patrol_rewards(p_patrol_id uuid) returns jsonb
language plpgsql security definer set search_path=public as $$
declare v_uid uuid:=auth.uid(); v_patrol record; v_first boolean:=false; v_item record; v_items jsonb:='[]'; v_xp jsonb; v_total_xp integer;
begin
 if v_uid is null then raise exception 'authentication required' using errcode='42501'; end if;
 select patrol.*,quest.display_name,quest.user_exp,quest.reward_pool_id into v_patrol from public.user_patrols patrol join public.canonical_quest_master quest on quest.version='2026-08-30' and quest.quest_id=coalesce(patrol.course_id,patrol.quest_id) and quest.is_production_enabled where patrol.id=p_patrol_id and patrol.user_id=v_uid for update of patrol;
 if not found then raise exception 'patrol not found' using errcode='P0002'; end if; if v_patrol.status='COMPLETED' then raise exception 'patrol rewards already claimed' using errcode='23505'; end if;
 if v_patrol.status<>'CLAIMABLE' and v_patrol.expires_at>now() then raise exception 'patrol is not complete' using errcode='23514'; end if; if v_patrol.has_battle_event and not coalesce(v_patrol.battle_resolved,false) then raise exception 'patrol battle must be resolved before claiming rewards' using errcode='23514'; end if;
 insert into public.user_quest_first_clears(user_id,quest_id) values(v_uid,coalesce(v_patrol.course_id,v_patrol.quest_id)) on conflict do nothing returning true into v_first; v_first:=coalesce(v_first,false); v_total_xp:=v_patrol.user_exp;
 for v_item in select * from public.canonical_quest_reward_pool_items item where item.version='2026-08-30' and item.reward_pool_id=v_patrol.reward_pool_id order by item.roll_index loop if floor(random()*10000)::integer<v_item.probability_bp then v_item.item_id:=public.resolve_canonical_reward_item(v_item.item_id); insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(v_uid,v_item.item_id,v_item.quantity,'クエストドロップ: '||v_patrol.display_name,'UNCLAIMED',now()+interval '24 hours'); v_items:=v_items||jsonb_build_array(jsonb_build_object('item_id',v_item.item_id,'quantity',v_item.quantity)); end if; end loop;
 v_xp:=public.apply_user_xp(v_uid,v_total_xp); update public.user_patrols set status='COMPLETED',rewards_accrued=jsonb_build_object('course_name',v_patrol.display_name,'cash',0,'xp',v_total_xp,'items',v_items,'first_clear',v_first) where id=p_patrol_id;
 perform public.evaluate_mission_progress(v_uid,'PATROL_CLEAR',1);
 return jsonb_build_object('status','success','patrol_id',p_patrol_id,'course_name',v_patrol.display_name,'cash',0,'xp',v_total_xp,'items',v_items,'first_clear',v_first,'level',v_xp->'level','current_xp',v_xp->'xp','leveled_up',v_xp->'leveled_up');
end $$;

delete from public.canonical_quest_reward_pool_items where version='2026-08-30';
insert into public.canonical_quest_reward_pool_items(version,reward_pool_id,roll_index,item_id,quantity,probability_bp)
select '2026-08-30',p->>'rewardPoolId',r.ordinality,(r.value->>'itemId'),(r.value->>'quantity')::integer,(r.value->>'probabilityBp')::integer
from jsonb_array_elements('[{"rewardPoolId":"QUEST_EASY_20260830","items":[{"itemId":"CHAR_EXP_S","quantity":1,"probabilityBp":10000},{"itemId":"EQUIP_EXP_S","quantity":1,"probabilityBp":2000}]},{"rewardPoolId":"QUEST_NORMAL_20260830","items":[{"itemId":"CHAR_EXP_M","quantity":1,"probabilityBp":10000},{"itemId":"EQUIP_EXP_M","quantity":1,"probabilityBp":10000},{"itemId":"SKILL_MANUAL","quantity":1,"probabilityBp":500}]},{"rewardPoolId":"QUEST_HARD_20260830","items":[{"itemId":"CHAR_EXP_L","quantity":1,"probabilityBp":10000},{"itemId":"EQUIP_EXP_L","quantity":1,"probabilityBp":10000},{"itemId":"SKILL_MANUAL","quantity":1,"probabilityBp":1200},{"itemId":"EQUIP_LB_PART","quantity":1,"probabilityBp":1200},{"itemId":"NORMAL_GACHA_TICKET_RANDOM","quantity":1,"probabilityBp":300}]}]'::jsonb) p cross join lateral jsonb_array_elements(p->'items') with ordinality r(value,ordinality);

create table if not exists public.canonical_quest_enemy_pool_entries(
 version text not null,pool_key text not null,area_id text not null,difficulty text not null,rarity text not null,
 character_id text not null,growth_pattern text not null,weight integer not null check(weight>0),local_affinity boolean not null,
 skill_loadout jsonb not null default '[]'::jsonb,is_production_enabled boolean not null default true,
 primary key(version,pool_key,character_id)
);
delete from public.canonical_quest_enemy_pool_entries where version='2026-08-30';
insert into public.canonical_quest_enemy_pool_entries
select '2026-08-30',x.pool_key,x.area_id,x.difficulty,x.rarity,x.character_id,x.growth_pattern,x.weight,x.local_affinity,x.skill_loadout,true
