create or replace function public.resolve_canonical_reward_item(p_reward_id text) returns text language plpgsql volatile security definer set search_path=public as $$
declare v_roll integer:=floor(random()*3)::integer;
begin
 if p_reward_id='NORMAL_GACHA_TICKET_RANDOM' then return (array['NORMAL_GACHA_TICKET_CHARACTER','NORMAL_GACHA_TICKET_SKILL','NORMAL_GACHA_TICKET_EQUIPMENT'])[v_roll+1]; end if;
 if p_reward_id='SPECIAL_TICKET_RANDOM' then return (array['SPECIAL_TICKET_CHARACTER','SPECIAL_TICKET_SKILL','SPECIAL_TICKET_EQUIPMENT'])[v_roll+1]; end if;
 if p_reward_id='SPECIAL_TICKET_SKILL_OR_EQUIPMENT' then return (array['SPECIAL_TICKET_SKILL','SPECIAL_TICKET_EQUIPMENT'])[floor(random()*2)::integer+1]; end if;
 return p_reward_id;
end $$;

create or replace function public.evaluate_mission_progress(p_user_id uuid,p_trigger_type text,p_progress_increment integer) returns void
language plpgsql security definer set search_path=public as $$
declare v_types text[];
begin
 if auth.uid() is not null and p_user_id is distinct from auth.uid() then raise exception 'Mission progress owner mismatch' using errcode='42501'; end if;
 if p_trigger_type is null or btrim(p_trigger_type)='' or p_progress_increment not between 1 and 1000 then raise exception 'Invalid mission progress event' using errcode='22023'; end if;
 v_types:=case p_trigger_type
  when 'GACHA_PULL' then array['NORMAL_FREE_GACHA_PULL_COUNT'] when 'CHAR_LEVEL_UP' then array['CHARACTER_ENHANCE_COUNT','CHARACTER_LEVEL_AT_LEAST']
  when 'GEAR_UPGRADE' then array['EQUIPMENT_ENHANCE_COUNT','EQUIPMENT_LEVEL_AT_LEAST'] when 'GEAR_LIMIT_BREAK' then array['EQUIPMENT_LIMIT_BREAK_COUNT']
  when 'SKILL_LIMIT_BREAK' then array['SKILL_ENHANCE_COUNT','SKILL_LEVEL_AT_LEAST'] when 'PATROL_CLEAR' then array['QUEST_COMPLETE_COUNT']
  when 'GUILD_JOIN' then array['GUILD_JOINED'] else array[p_trigger_type] end;
 update public.user_missions um set current_progress=least(m.target_value,um.current_progress+p_progress_increment),progress_val=least(m.target_value,um.current_progress+p_progress_increment),status=case when um.current_progress+p_progress_increment>=m.target_value then 'CLEAR' else 'PROGRESS' end,updated_at=now()
 from public.missions m where um.user_id=p_user_id and um.mission_id=m.id and m.is_enabled and m.trigger_type=any(v_types) and um.status='PROGRESS';
end $$;

create or replace function public.claim_mission_reward(p_mission_id text) returns jsonb
language plpgsql security definer set search_path=public as $$
declare v_uid uuid:=auth.uid(); v_mission public.missions%rowtype; v_progress public.user_missions%rowtype; v_reward_item_id text;
begin
 if v_uid is null or p_mission_id is null then raise exception 'Player authentication required' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(v_uid::text||':missions',0)); perform public.sync_current_missions();
 select * into v_progress from public.user_missions where user_id=v_uid and mission_id=p_mission_id for update;
 if not found or v_progress.status<>'CLEAR' then raise exception 'Mission reward is not claimable' using errcode='23514'; end if;
 select * into strict v_mission from public.missions where id=p_mission_id and is_enabled;
 update public.user_missions set status='CLAIMED',claimed_at=clock_timestamp(),updated_at=clock_timestamp() where id=v_progress.id;
 v_reward_item_id:=public.resolve_canonical_reward_item(v_mission.reward_item_id);
 if coalesce(v_reward_item_id,'')<>'' and coalesce(v_mission.reward_quantity,0)>0 then insert into public.presents(user_id,item_id,quantity,message,status,sent_at,expire_at) values(v_uid,v_reward_item_id,v_mission.reward_quantity,'ミッション報酬: '||v_mission.title,'UNCLAIMED',now(),now()+interval '30 days'); end if;
 if v_mission.cash_reward>0 then insert into public.presents(user_id,item_id,quantity,message,status,sent_at,expire_at) values(v_uid,'CASH',v_mission.cash_reward,'ミッション報酬: '||v_mission.title,'UNCLAIMED',now(),now()+interval '30 days'); end if;
 insert into public.user_missions(user_id,mission_id,current_progress,progress_val,status) select v_uid,next.id,0,0,'PROGRESS' from public.missions next where next.is_enabled and next.category='NORMAL' and next.prerequisite_mission_id=p_mission_id on conflict(user_id,mission_id) do nothing;
 return jsonb_build_object('claimed',true,'mission_id',p_mission_id,'item_id',v_reward_item_id,'quantity',v_mission.reward_quantity,'cash',v_mission.cash_reward);
end $$;

create or replace function public.claim_all_mission_rewards(p_mission_ids text[]) returns jsonb
language plpgsql security definer set search_path=public as $$
declare v_uid uuid:=auth.uid(); v_entry record; v_count integer:=0; v_reward_item_id text;
begin
 if v_uid is null or p_mission_ids is null or cardinality(p_mission_ids) not between 1 and 100 then raise exception 'Invalid mission claim request' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended(v_uid::text||':missions',0)); perform public.sync_current_missions();
 for v_entry in select um.id user_mission_id,um.mission_id,m.* from public.user_missions um join public.missions m on m.id=um.mission_id and m.is_enabled where um.user_id=v_uid and um.status='CLEAR' and um.mission_id in(select distinct unnest(p_mission_ids)) for update of um loop
  update public.user_missions set status='CLAIMED',claimed_at=now(),updated_at=now() where id=v_entry.user_mission_id;
  v_reward_item_id:=public.resolve_canonical_reward_item(v_entry.reward_item_id);
  if coalesce(v_reward_item_id,'')<>'' and coalesce(v_entry.reward_quantity,0)>0 then insert into public.presents(user_id,item_id,quantity,message,status,sent_at,expire_at) values(v_uid,v_reward_item_id,v_entry.reward_quantity,'ミッション報酬: '||v_entry.title,'UNCLAIMED',now(),now()+interval '30 days'); end if;
  if v_entry.cash_reward>0 then insert into public.presents(user_id,item_id,quantity,message,status,sent_at,expire_at) values(v_uid,'CASH',v_entry.cash_reward,'ミッション報酬: '||v_entry.title,'UNCLAIMED',now(),now()+interval '30 days'); end if;
  insert into public.user_missions(user_id,mission_id,current_progress,progress_val,status) select v_uid,next.id,0,0,'PROGRESS' from public.missions next where next.is_enabled and next.category='NORMAL' and next.prerequisite_mission_id=v_entry.mission_id on conflict(user_id,mission_id) do nothing;
  v_count:=v_count+1;
 end loop;
 return jsonb_build_object('claimed_count',v_count);
end $$;

-- Login cycle replacement; CASH is intentionally absent.
delete from public.login_bonus_master;
insert into public.login_bonus_master(day_number,item_id,quantity,item_name,is_featured)
