update public.login_bonus_master set item_name=case item_id when 'CHAR_EXP_M' then '強化ドリンク・中' when 'EQUIP_EXP_M' then 'カスタムオイル・中' when 'NORMAL_GACHA_TICKET_CHARACTER' then 'キャラクターガチャチケット' when 'SKILL_MANUAL' then 'スキル指南書' when 'CHAR_EXP_L' then '強化ドリンク・大' when 'NORMAL_GACHA_TICKET_SKILL' then 'スキルガチャチケット' when 'EQUIP_LB_PART' then '改造パーツ' when 'EQUIP_EXP_L' then 'カスタムオイル・大' when 'NORMAL_GACHA_TICKET_EQUIPMENT' then '装備ガチャチケット' when 'SPECIAL_TICKET_SKILL' then 'SPスキルチケット' when 'AWAKENING_BOOK' then '覚醒の書' when 'SPECIAL_TICKET_CHARACTER' then 'SPキャラクターチケット' else item_id end;
create or replace function public.on_login_bonus_mission_progress() returns trigger language plpgsql security definer set search_path=public as $$ begin perform public.evaluate_mission_progress(new.user_id,'LOGIN_DAY_COUNT',1); return new; end $$;
drop trigger if exists login_bonus_mission_progress on public.user_login_bonuses;
create trigger login_bonus_mission_progress after insert or update of last_claimed_at on public.user_login_bonuses for each row execute function public.on_login_bonus_mission_progress();

-- Canonical Gacha rates. Special remains gated closed by feature_operating_states.
delete from public.gacha_rarity_rates;
insert into public.gacha_rarity_rates(gacha_id,rarity,weight)
select x.gacha_id,x.rarity,x.weight from jsonb_to_recordset('[{"gacha_id":"CHAR_NORMAL","rarity":"N","weight":60},{"gacha_id":"CHAR_NORMAL","rarity":"R","weight":30},{"gacha_id":"CHAR_NORMAL","rarity":"SR","weight":9},{"gacha_id":"CHAR_NORMAL","rarity":"SSR","weight":1},{"gacha_id":"CHAR_SPECIAL","rarity":"R","weight":70},{"gacha_id":"CHAR_SPECIAL","rarity":"SR","weight":27},{"gacha_id":"CHAR_SPECIAL","rarity":"SSR","weight":3},{"gacha_id":"SKILL_NORMAL","rarity":"N","weight":50},{"gacha_id":"SKILL_NORMAL","rarity":"R","weight":30},{"gacha_id":"SKILL_NORMAL","rarity":"SR","weight":17},{"gacha_id":"SKILL_NORMAL","rarity":"SSR","weight":3},{"gacha_id":"SKILL_SPECIAL","rarity":"R","weight":60},{"gacha_id":"SKILL_SPECIAL","rarity":"SR","weight":35},{"gacha_id":"SKILL_SPECIAL","rarity":"SSR","weight":5},{"gacha_id":"EQUIP_NORMAL","rarity":"N","weight":45},{"gacha_id":"EQUIP_NORMAL","rarity":"R","weight":30},{"gacha_id":"EQUIP_NORMAL","rarity":"SR","weight":20},{"gacha_id":"EQUIP_NORMAL","rarity":"SSR","weight":5},{"gacha_id":"EQUIP_SPECIAL","rarity":"R","weight":55},{"gacha_id":"EQUIP_SPECIAL","rarity":"SR","weight":38},{"gacha_id":"EQUIP_SPECIAL","rarity":"SSR","weight":7}]'::jsonb) x(gacha_id text,rarity text,weight integer);
update public.gacha_masters master set cost_cash=x.cost_cash from jsonb_to_recordset('[{"id":"CHAR_NORMAL","cost_cash":100},{"id":"CHAR_SPECIAL","cost_cash":300},{"id":"SKILL_NORMAL","cost_cash":100},{"id":"SKILL_SPECIAL","cost_cash":200},{"id":"EQUIP_NORMAL","cost_cash":100},{"id":"EQUIP_SPECIAL","cost_cash":200}]'::jsonb) x(id text,cost_cash integer) where master.id=x.id;

-- PvP repeating win/loss CASH is removed. Daily reward is guarded by game day.
update public.pvp_match_rewards_master set cash_reward=0 where result in('VICTORY','DEFEAT');
delete from public.canonical_pvp_ranking_rewards;

create or replace function public.finalize_pvp_battle(p_replay_id uuid,p_result jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_replay public.battle_replay_sessions%rowtype; v_win boolean; v_player integer; v_opponent integer; v_delta integer; v_new integer; v_final jsonb; v_name text;
begin
 select * into v_replay from public.battle_replay_sessions where id=p_replay_id for update;
 if not found then raise exception 'PvP replay not found' using errcode='P0002'; end if;
 if v_replay.battle_mode<>'PVP' or v_replay.resolution_authority<>'PVP_SERVER' then raise exception 'replay is not official PvP' using errcode='42501'; end if;
 if v_replay.finalization_status='FINALIZED' then return v_replay.finalization_result; end if;
 if v_replay.status<>'PENDING' or v_replay.finalization_status<>'PENDING' then raise exception 'PvP replay is not finalizable' using errcode='23514'; end if;
 perform public.validate_official_battle_result(p_result); v_win:=p_result->>'winner'='PLAYER';
 v_player:=coalesce((v_replay.official_context->>'playerRankPointsAtStart')::integer,1000); v_opponent:=coalesce((v_replay.official_context->>'opponentRankPointsAtStart')::integer,1000); v_delta:=public.canonical_pvp_rating_delta(v_player,v_opponent,case when v_win then 'WIN' else 'LOSS' end);
 insert into public.pvp_ranks(user_id,rank_points,daily_wins,season_wins,updated_at) values(v_replay.requester_user_id,greatest(1000+v_delta,0),case when v_win then 1 else 0 end,case when v_win then 1 else 0 end,now()) on conflict(user_id) do update set rank_points=greatest(public.pvp_ranks.rank_points+v_delta,0),daily_wins=public.pvp_ranks.daily_wins+case when v_win then 1 else 0 end,season_wins=public.pvp_ranks.season_wins+case when v_win then 1 else 0 end,updated_at=now() returning rank_points into v_new;
 select username into v_name from public.users where id=v_replay.requester_user_id; insert into public.pvp_defense_logs(user_id,attacker_id,attacker_name,result,points_change) values(v_replay.source_reference_id,v_replay.requester_user_id,v_name,case when v_win then 'DEFEAT' else 'VICTORY' end,-v_delta);
 v_final:=p_result||jsonb_build_object('mode','PVP','oldRating',v_player,'opponentRating',v_opponent,'rankDelta',v_delta,'newRankPoints',v_new,'remainingPvpPoints',coalesce((v_replay.official_context->>'remainingPvpPoints')::integer,0),'rewards',jsonb_build_object('cash',0,'diamonds',0,'xp',0));
 insert into public.battle_replay_events(battle_replay_session_id,event_index,round_number,event_type,payload) select p_replay_id,greatest(coalesce((e.value->>'index')::integer,e.ordinality::integer-1),0),greatest(coalesce((e.value->>'round')::integer,1),1),coalesce(nullif(e.value->>'type',''),'UNKNOWN'),coalesce(e.value->'payload','{}'::jsonb) from jsonb_array_elements(p_result->'events') with ordinality e(value,ordinality) on conflict do nothing;
 update public.battle_replay_sessions set status='RESOLVED',result=v_final,resolved_at=now(),finalization_status='FINALIZED',finalized_at=now(),finalization_result=v_final where id=p_replay_id;
 perform public.evaluate_mission_progress(v_replay.requester_user_id,'PVP_BATTLE_COUNT',1); if v_win then perform public.evaluate_mission_progress(v_replay.requester_user_id,'PVP_WIN_COUNT',1); end if;
 return v_final;
end $$;

create table if not exists public.canonical_daily_activity_claims(
 game_day date not null,user_id uuid not null references public.users(id) on delete cascade,source_key text not null,
 source_ref uuid,reward_payload jsonb not null,created_at timestamptz not null default now(),primary key(game_day,user_id,source_key)
);

create or replace function public.remove_legacy_pvp_cash_before_finalize() returns trigger
language plpgsql security definer set search_path=public as $$
declare v_legacy_cash integer;
begin
 if old.finalization_status<>'FINALIZED' and new.finalization_status='FINALIZED' and new.battle_mode='PVP' then
  v_legacy_cash:=greatest(coalesce((new.finalization_result#>>'{rewards,cash}')::integer,0),0);
  if v_legacy_cash>0 then update public.users set cash=cash-v_legacy_cash where id=new.requester_user_id; end if;
  new.finalization_result:=jsonb_set(new.finalization_result,'{rewards,cash}','0'::jsonb,true);
  new.result:=jsonb_set(new.result,'{rewards,cash}','0'::jsonb,true);
 end if;
 return new;
end $$;
drop trigger if exists remove_legacy_pvp_cash_before_finalize on public.battle_replay_sessions;
create trigger remove_legacy_pvp_cash_before_finalize before update of finalization_status on public.battle_replay_sessions for each row execute function public.remove_legacy_pvp_cash_before_finalize();

create or replace function public.on_canonical_daily_activity_finalized() returns trigger
language plpgsql security definer set search_path=public as $$
declare v_day date:=(new.finalized_at at time zone 'Asia/Tokyo')::date; v_count integer; v_consumed integer; v_key text;
begin
 if old.finalization_status='FINALIZED' or new.finalization_status<>'FINALIZED' then return new; end if;
 if new.battle_mode='PVP' then
  v_key:='PVP_BATTLE:'||new.id::text;
  insert into public.canonical_daily_activity_claims values(v_day,new.requester_user_id,v_key,new.id,'[{"itemId":"CHAR_EXP_S","quantity":1}]',now()) on conflict do nothing;
  if found then insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(new.requester_user_id,'CHAR_EXP_S',1,'PvPバトル報酬','UNCLAIMED',now()+interval '30 days'); end if;
  select count(*) into v_count from public.battle_replay_sessions where requester_user_id=new.requester_user_id and battle_mode='PVP' and finalization_status='FINALIZED' and (finalized_at at time zone 'Asia/Tokyo')::date=v_day;
  if v_count>=3 then
   insert into public.canonical_daily_activity_claims values(v_day,new.requester_user_id,'PVP_DAILY_3',new.id,'[{"itemId":"SKILL_MANUAL","quantity":1},{"itemId":"CASH","quantity":40}]',now()) on conflict do nothing;
   if found then insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(new.requester_user_id,'SKILL_MANUAL',1,'PvPデイリー報酬','UNCLAIMED',now()+interval '30 days'),(new.requester_user_id,'CASH',40,'PvPデイリー報酬','UNCLAIMED',now()+interval '30 days'); end if;
  end if;
 elsif new.battle_mode='RAID' then
  v_key:='RAID_BATTLE:'||new.id::text;
  insert into public.canonical_daily_activity_claims values(v_day,new.requester_user_id,v_key,new.id,'[{"itemId":"EQUIP_EXP_S","quantity":1}]',now()) on conflict do nothing;
  if found then insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(new.requester_user_id,'EQUIP_EXP_S',1,'レイドバトル報酬','UNCLAIMED',now()+interval '30 days'); end if;
  select count(*) into v_count from public.battle_replay_sessions where requester_user_id=new.requester_user_id and battle_mode='RAID' and finalization_status='FINALIZED' and (finalized_at at time zone 'Asia/Tokyo')::date=v_day;
  if v_count>=3 then
   insert into public.canonical_daily_activity_claims values(v_day,new.requester_user_id,'RAID_DAILY_3',new.id,'[{"itemId":"CHAR_EXP_M","quantity":1},{"itemId":"CASH","quantity":40}]',now()) on conflict do nothing;
   if found then insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(new.requester_user_id,'CHAR_EXP_M',1,'レイドデイリー報酬','UNCLAIMED',now()+interval '30 days'),(new.requester_user_id,'CASH',40,'レイドデイリー報酬','UNCLAIMED',now()+interval '30 days'); end if;
  end if;
  select coalesce(sum(progress.raid_points_consumed),0) into v_consumed from public.raid_instance_user_progress progress join public.raid_bosses boss on boss.id=progress.raid_boss_instance_id where progress.user_id=new.requester_user_id and boss.raid_day_key=v_day::text;
  if v_consumed>=5 then
   insert into public.canonical_daily_activity_claims values(v_day,new.requester_user_id,'RAID_POINTS_5',new.id,'[{"itemId":"EQUIP_LB_PART","quantity":1}]',now()) on conflict do nothing;
   if found then insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(new.requester_user_id,'EQUIP_LB_PART',1,'レイド参加報酬','UNCLAIMED',now()+interval '30 days'); end if;
  end if;
 end if;
 return new;
end $$;
drop trigger if exists canonical_daily_activity_finalized on public.battle_replay_sessions;
create trigger canonical_daily_activity_finalized after update of finalization_status on public.battle_replay_sessions for each row execute function public.on_canonical_daily_activity_finalized();

create or replace function public.on_canonical_hard_quest_complete() returns trigger
language plpgsql security definer set search_path=public as $$
declare v_day date:=(clock_timestamp() at time zone 'Asia/Tokyo')::date; v_difficulty text;
begin
 if old.status='COMPLETED' or new.status<>'COMPLETED' then return new; end if;
 select difficulty into v_difficulty from public.canonical_quest_master where version='2026-08-30' and quest_id=coalesce(new.course_id,new.quest_id) and is_production_enabled;
 if v_difficulty='HARD' then
  insert into public.canonical_daily_activity_claims values(v_day,new.user_id,'QUEST_HARD_FIRST',new.id,'[{"itemId":"CASH","quantity":20}]',now()) on conflict do nothing;
  if found then insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(new.user_id,'CASH',20,'HARDクエスト本日初回報酬','UNCLAIMED',now()+interval '30 days'); end if;
 end if;
 return new;
end $$;
drop trigger if exists canonical_hard_quest_complete on public.user_patrols;
create trigger canonical_hard_quest_complete after update of status on public.user_patrols for each row execute function public.on_canonical_hard_quest_complete();

-- Raid variant/day authority. rotation_date is the existing server Raid Day authority.
create table if not exists public.canonical_raid_variants(
 raid_variant_id text primary key,area_id text not null,raid_name text not null,max_hp bigint not null,atk integer not null,
 def integer not null,spd integer not null,member_character_ids jsonb not null,is_production_enabled boolean not null default true,version text not null
);
update public.canonical_raid_variants set is_production_enabled=false;
insert into public.canonical_raid_variants
select x.raid_variant_id,x.area_id,x.raid_name,x.max_hp,x.atk,x.def,x.spd,x.member_character_ids,true,'2026-08-30'
from jsonb_to_recordset('[{"raid_variant_id":"RAID_SHINJUKU_V1","area_id":"SHINJUKU","raid_name":"キングス・クラウン","max_hp":32000000,"atk":9500,"def":6200,"spd":390,"member_character_ids":["char_reiji_01","char_mio_01","char_takuro_01","char_leon_01","char_kageyama_01"]},{"raid_variant_id":"RAID_SHIBUYA_V1","area_id":"SHIBUYA","raid_name":"ハイスピード・スターズ","max_hp":28000000,"atk":8800,"def":5500,"spd":470,"member_character_ids":["char_ageha_01","char_leo_01","char_sora_01","char_reina_01","char_noa_01"]},{"raid_variant_id":"RAID_IKEBUKURO_V1","area_id":"IKEBUKURO","raid_name":"アイアンウォール","max_hp":36000000,"atk":8200,"def":8200,"spd":340,"member_character_ids":["char_koharu_01","char_takeshi_01","char_momoko_01","char_riki_01","char_sakura_01"]},{"raid_variant_id":"RAID_ROPPONGI_V1","area_id":"ROPPONGI","raid_name":"ロイヤル・フラッシュ","max_hp":34000000,"atk":8700,"def":7700,"spd":390,"member_character_ids":["char_kaede_01","char_taiga_01","char_maya_01","char_seiya_01","char_cecile_01"]},{"raid_variant_id":"RAID_AKIHABARA_V1","area_id":"AKIHABARA","raid_name":"グリッチ・コード","max_hp":30000000,"atk":8400,"def":6500,"spd":430,"member_character_ids":["char_karen_01","char_miyabi_01","char_alice_01","char_rui_01","char_maya_01"]},{"raid_variant_id":"RAID_KAWASAKI_V1","area_id":"KAWASAKI","raid_name":"ブレイクダウン","max_hp":38000000,"atk":10500,"def":6000,"spd":350,"member_character_ids":["char_go_01","char_kengo_01","char_tetsu_01","char_lucas_01","char_riki_01"]},{"raid_variant_id":"RAID_YOKOHAMA_V1","area_id":"YOKOHAMA","raid_name":"ブルー・レクイエム","max_hp":35000000,"atk":8900,"def":7200,"spd":390,"member_character_ids":["char_genji_01","char_long_01","char_sakura_01","char_cecile_01","char_taiga_01"]}]'::jsonb) x(raid_variant_id text,area_id text,raid_name text,max_hp bigint,atk integer,def integer,spd integer,member_character_ids jsonb)
on conflict(raid_variant_id) do update set area_id=excluded.area_id,raid_name=excluded.raid_name,max_hp=excluded.max_hp,atk=excluded.atk,def=excluded.def,spd=excluded.spd,member_character_ids=excluded.member_character_ids,is_production_enabled=true,version='2026-08-30';

delete from public.canonical_raid_boss_master;
insert into public.canonical_raid_boss_master(boss_id,town_id,display_name,profile_type,attribute,reference_level,max_hp,atk,def,spd,luk,skill_loadout,tuning_status,is_production_enabled)
select raid_variant_id,lower(area_id),raid_name,'PARTY','NEUTRAL',30,max_hp,atk,def,spd,0,'[]'::jsonb,'PRODUCTION_FROZEN',true from public.canonical_raid_variants where version='2026-08-30' and is_production_enabled;
insert into public.raid_boss_master(id,name,base_hp,base_atk,base_def,spd,duration_minutes,rewards,boss_name,level,max_hp,atk,def,luk,skills,enabled,profile_type,attribute,town_id)
select boss_id,display_name,max_hp,atk,def,spd,1440,'[]'::jsonb,display_name,reference_level,max_hp,atk,def,luk,skill_loadout,true,profile_type,attribute,town_id from public.canonical_raid_boss_master
on conflict(id) do update set name=excluded.name,base_hp=excluded.base_hp,base_atk=excluded.base_atk,base_def=excluded.base_def,spd=excluded.spd,boss_name=excluded.boss_name,level=excluded.level,max_hp=excluded.max_hp,atk=excluded.atk,def=excluded.def,luk=excluded.luk,skills=excluded.skills,enabled=true,profile_type=excluded.profile_type,attribute=excluded.attribute,town_id=excluded.town_id;
update public.raid_boss_master set enabled=false where id not in(select raid_variant_id from public.canonical_raid_variants where is_production_enabled);
update public.raid_bosses set status='EXPIRED',outcome='LEGACY_REPLACED',outcome_finalized_at=coalesce(outcome_finalized_at,now()) where status='ACTIVE' and coalesce(boss_master_id,boss_id) not in(select raid_variant_id from public.canonical_raid_variants where is_production_enabled);

alter table public.raid_bosses add column if not exists raid_variant_id text references public.canonical_raid_variants(raid_variant_id),
 add column if not exists raid_day_key text,add column if not exists cleared_at timestamptz,add column if not exists respawn_after timestamptz;
update public.raid_bosses set raid_day_key=coalesce(raid_day_key,rotation_date::text),respawn_after=case when current_hp=0 then coalesce(respawn_after,outcome_finalized_at+interval '5 minutes') else respawn_after end;

create or replace function public.canonical_raid_rotation_pair(p_date date) returns text[] language sql immutable as $$
 with towns as(select array['shinjuku','shibuya','ikebukuro','roppongi','akihabara','kawasaki','yokohama']::text[] value),pairs as(select array[value[i],value[j]] pair,row_number() over(order by i,j)-1 idx from towns,generate_subscripts(value,1)i,generate_subscripts(value,1)j where i<j)
 select pair from pairs where idx=mod((p_date-date '2026-08-30')::integer,21)
$$;

create or replace function public.rotate_daily_raids() returns void language plpgsql security definer set search_path=public as $$
declare v_today date:=(clock_timestamp() at time zone 'Asia/Tokyo')::date; v_pair text[]; v_area text; v_variant public.canonical_raid_variants%rowtype; v_start timestamptz; v_end timestamptz; v_cleared record;
begin
 perform pg_advisory_xact_lock(hashtextextended('CANONICAL_RAID_ROTATION:'||v_today::text,0));
 for v_cleared in select id from public.raid_bosses where status='ACTIVE' and (current_hp=0 or expires_at<=now()) for update loop perform public.finalize_expired_raid_instance(v_cleared.id); end loop;
 for v_cleared in select id from public.raid_bosses where status='CLEARED' and raid_day_key=v_today::text and respawn_after<=now() for update loop perform public.respawn_cleared_raid_slot(v_cleared.id); end loop;
 v_pair:=public.canonical_raid_rotation_pair(v_today); v_start:=(v_today::timestamp at time zone 'Asia/Tokyo'); v_end:=v_start+interval '24 hours';
 foreach v_area in array v_pair loop
  if not exists(select 1 from public.raid_bosses where raid_day_key=v_today::text and base_id=v_area and status='ACTIVE') and not exists(select 1 from public.raid_bosses where raid_day_key=v_today::text and base_id=v_area and status='CLEARED' and respawn_after>now()) then
   select * into v_variant from public.canonical_raid_variants where area_id=upper(v_area) and is_production_enabled order by raid_variant_id limit 1;
   insert into public.raid_bosses(boss_id,boss_master_id,current_hp,max_hp,base_id,status,spawned_at,expires_at,cycle_id,rotation_date,raid_variant_id,raid_day_key) values(v_variant.raid_variant_id,v_variant.raid_variant_id,v_variant.max_hp,v_variant.max_hp,v_area,'ACTIVE',greatest(now(),v_start),v_end,gen_random_uuid(),v_today,v_variant.raid_variant_id,v_today::text);
  end if;
 end loop;
end $$;

create or replace function public.start_raid_battle(p_instance_id uuid,p_character_ids text[],p_tactic text default 'ATTACK_PRIORITY') returns jsonb
language plpgsql security definer set search_path=public as $$
declare v_uid uuid:=auth.uid(); v_user public.users%rowtype; v_instance record; v_cost integer; v_cost_type text; v_guild uuid; v_players jsonb; v_enemy jsonb:='[]'; v_member text; v_entry record; v_skill_refs jsonb; v_skills jsonb; v_replay uuid; v_seed bigint; v_slot integer:=0;
begin
 if v_uid is null then raise exception 'authentication required' using errcode='42501'; end if;
 if p_tactic not in('ATTACK_PRIORITY','HEAL_PRIORITY','SKILL_PRIORITY','BALANCED','WEAKNESS_FOCUS') then raise exception 'invalid tactic' using errcode='22023'; end if;
 perform public.sync_and_recover_vitality_and_pvp_points(v_uid); select * into v_user from public.users where id=v_uid for update;
 if v_user.level<5 then raise exception 'player level 5 is required' using errcode='23514'; end if;
 select boss.*,variant.raid_name,variant.atk,variant.def,variant.spd,variant.member_character_ids into v_instance from public.raid_bosses boss join public.canonical_raid_variants variant on variant.raid_variant_id=boss.raid_variant_id where boss.id=p_instance_id and boss.status='ACTIVE' and boss.expires_at>now() for update of boss;
 if not found then raise exception 'Raid instance is not active' using errcode='P0002'; end if;
 if not v_user.raid_free_entry_consumed then v_cost:=0;v_cost_type:='FREE_FIRST';update public.users set raid_free_entry_consumed=true where id=v_uid;
 elsif v_user.raid_points>=1 then v_cost:=1;v_cost_type:='RAID_POINT';update public.users set raid_points=raid_points-1,raid_points_last_recovered_at=case when raid_points=5 then now() else raid_points_last_recovered_at end where id=v_uid;v_user.raid_points:=v_user.raid_points-1;
 else raise exception 'insufficient Raid points' using errcode='23514'; end if;
 select guild_id into v_guild from public.guild_members where user_id=v_uid; v_players:=public.build_server_battle_snapshot(v_uid,p_character_ids,'PLAYER');
 for v_member in select value from jsonb_array_elements_text(v_instance.member_character_ids) loop
  v_slot:=v_slot+1; select * into v_entry from public.canonical_quest_enemy_pool_entries where version='2026-08-30' and character_id=v_member and difficulty='HARD' order by(local_affinity)desc,weight desc limit 1;
  v_skill_refs:=coalesce(v_entry.skill_loadout,(select jsonb_agg(skill_id order by skill_id) from(select skill_id from public.canonical_skill_master where version='2026-08-21' and exclusive_character_id=v_member order by skill_id limit 2)s),(select jsonb_agg(skill_id order by skill_id) from(select skill_id from public.canonical_skill_master where version='2026-08-21' and exclusive_character_id is null order by skill_id limit 2)s),'[]'::jsonb);
  select coalesce(jsonb_agg(jsonb_build_object('id',s.skill_id,'name',s.display_name,'activationType',s.activation_type,'cooldown',s.cooldown,'availableFromRound',s.available_from_round,'target',s.target,'effects',s.effects,'exclusiveCharacterId',s.exclusive_character_id) order by x.ordinality),'[]') into v_skills from jsonb_array_elements_text(v_skill_refs) with ordinality x(skill_id,ordinality) join public.canonical_skill_master s on s.version='2026-08-21' and s.skill_id=x.skill_id;
  v_enemy:=v_enemy||jsonb_build_array(jsonb_build_object('id','raid_'||v_instance.id||'_'||v_slot,'characterId',v_member,'name',coalesce((select display_name from public.canonical_character_master where version='2026-08-21' and character_id=v_member),v_member),'team','ENEMY','alignment',coalesce((select attribute from public.canonical_character_master where version='2026-08-21' and character_id=v_member),'NEUTRAL'),'level',30,'stats',jsonb_build_object('hp',ceil(v_instance.max_hp::numeric/5),'atk',v_instance.atk,'def',v_instance.def,'spd',v_instance.spd,'luk',0),'equippedSkillRefs',v_skill_refs,'skills',v_skills,'equipment','[]'::jsonb));
 end loop;
 v_seed:=floor(random()*2147483646)::bigint+1;
 insert into public.battle_replay_sessions(requester_user_id,battle_mode,source_reference_id,tactic_id,random_seed,player_snapshot,enemy_snapshot,resolution_authority,finalization_status,official_context) values(v_uid,'RAID',p_instance_id,p_tactic,v_seed,v_players,v_enemy,'RAID_SERVER','PENDING',jsonb_build_object('guildIdSnapshot',v_guild,'costType',v_cost_type,'cost',v_cost,'remainingRaidPoints',v_user.raid_points,'bossHpAtStart',v_instance.current_hp,'bossMaxHp',v_instance.max_hp,'baseId',v_instance.base_id,'raidDayKey',v_instance.raid_day_key,'raidVariantId',v_instance.raid_variant_id)) returning id into v_replay;
 return jsonb_build_object('replay_session_id',v_replay,'player_snapshot',v_players,'enemy_snapshot',v_enemy,'cost_type',v_cost_type,'cost',v_cost,'remaining_raid_points',v_user.raid_points,'guild_id_snapshot',v_guild);
end $$;

create table if not exists public.raid_clear_reward_claims(
 raid_day_key text not null,user_id uuid not null references public.users(id) on delete cascade,reward_type text not null default 'CLEAR_REWARD',
 source_instance_id uuid not null references public.raid_bosses(id),ticket_roll boolean not null default false,ticket_item_id text,awakening_roll boolean not null default false,
 delivery_status text not null default 'PENDING',last_error text,created_at timestamptz not null default now(),delivered_at timestamptz,
 primary key(raid_day_key,user_id,reward_type),check(reward_type='CLEAR_REWARD')
);
alter table public.raid_clear_reward_claims add column if not exists ticket_item_id text;
alter table public.raid_clear_reward_claims alter column ticket_roll set default false,alter column awakening_roll set default false;
update public.raid_clear_reward_claims set ticket_item_id=public.resolve_canonical_reward_item('NORMAL_GACHA_TICKET_RANDOM') where ticket_roll and ticket_item_id is null;
create table if not exists public.raid_clear_reward_deliveries(
 raid_day_key text not null,user_id uuid not null,reward_type text not null,item_id text not null,quantity integer not null,
 source_instance_id uuid not null,delivered_at timestamptz not null default now(),
 primary key(raid_day_key,user_id,reward_type,item_id),
 foreign key(raid_day_key,user_id,reward_type) references public.raid_clear_reward_claims(raid_day_key,user_id,reward_type)
);

create or replace function public.grant_canonical_raid_day_clear_reward(p_instance_id uuid,p_user_id uuid) returns jsonb
language plpgsql security definer set search_path=public as $$
declare v_instance public.raid_bosses%rowtype; v_claim public.raid_clear_reward_claims%rowtype; v_item record; v_inserted boolean; v_row_count integer;
begin
 select * into v_instance from public.raid_bosses where id=p_instance_id for update;
 if not found or v_instance.status<>'CLEARED' or v_instance.raid_day_key is null then return jsonb_build_object('eligible',false); end if;
 if not exists(select 1 from public.raid_instance_user_progress where raid_boss_instance_id=p_instance_id and user_id=p_user_id and finalized_battles>0) then return jsonb_build_object('eligible',false); end if;
 insert into public.raid_clear_reward_claims(raid_day_key,user_id,reward_type,source_instance_id)
 values(v_instance.raid_day_key,p_user_id,'CLEAR_REWARD',p_instance_id)
 on conflict do nothing; get diagnostics v_row_count=row_count; v_inserted:=v_row_count=1;
 select * into v_claim from public.raid_clear_reward_claims where raid_day_key=v_instance.raid_day_key and user_id=p_user_id and reward_type='CLEAR_REWARD' for update;
 if v_inserted then
  update public.raid_clear_reward_claims set ticket_roll=random()<0.30,ticket_item_id=public.resolve_canonical_reward_item('NORMAL_GACHA_TICKET_RANDOM'),awakening_roll=random()<0.01
  where raid_day_key=v_instance.raid_day_key and user_id=p_user_id and reward_type='CLEAR_REWARD' returning * into v_claim;
 end if;
 if not v_inserted and v_claim.delivery_status='DELIVERED' then return jsonb_build_object('eligible',true,'already_claimed',true); end if;
 begin
  for v_item in select * from (values('SKILL_MANUAL'::text,1,true),(v_claim.ticket_item_id,1,v_claim.ticket_roll),('AWAKENING_BOOK',1,v_claim.awakening_roll)) x(item_id,quantity,selected) where selected loop
   insert into public.raid_clear_reward_deliveries values(v_claim.raid_day_key,p_user_id,'CLEAR_REWARD',v_item.item_id,v_item.quantity,v_claim.source_instance_id,now()) on conflict do nothing;
   if found then insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(p_user_id,v_item.item_id,v_item.quantity,'レイドクリア報酬','UNCLAIMED',now()+interval '30 days'); end if;
  end loop;
  update public.raid_clear_reward_claims set delivery_status='DELIVERED',delivered_at=now(),last_error=null where raid_day_key=v_claim.raid_day_key and user_id=p_user_id and reward_type='CLEAR_REWARD';
 exception when others then
  update public.raid_clear_reward_claims set delivery_status='PENDING',last_error=sqlstate where raid_day_key=v_claim.raid_day_key and user_id=p_user_id and reward_type='CLEAR_REWARD';
 end;
 return jsonb_build_object('eligible',true,'already_claimed',not v_inserted,'ticket_roll',v_claim.ticket_roll,'awakening_roll',v_claim.awakening_roll);
end $$;

create or replace function public.finalize_expired_raid_instance(p_instance_id uuid) returns void
language plpgsql security definer set search_path=public as $$
declare v_instance public.raid_bosses%rowtype; v_user record;
begin
 select * into v_instance from public.raid_bosses where id=p_instance_id for update;
 if not found or v_instance.outcome_finalized_at is not null then return; end if;
 if v_instance.status='ACTIVE' and v_instance.current_hp>0 and v_instance.expires_at>clock_timestamp() then return; end if;
 if v_instance.current_hp=0 then
  update public.raid_bosses set status='CLEARED',outcome='DEFEAT_SUCCESS',outcome_finalized_at=now(),cleared_at=now(),respawn_after=now()+interval '5 minutes',raid_day_key=coalesce(raid_day_key,rotation_date::text) where id=p_instance_id returning * into v_instance;
  for v_user in select user_id from public.raid_instance_user_progress where raid_boss_instance_id=p_instance_id and finalized_battles>0 loop
   perform public.grant_canonical_raid_day_clear_reward(p_instance_id,v_user.user_id);
  end loop;
 else
  update public.raid_bosses set status='EXPIRED',outcome='TIMEOUT_FAILURE',outcome_finalized_at=now() where id=p_instance_id;
 end if;
end $$;

-- Same-day respawn inherits raid_day_key and variant; a new day can rotate variants.
create or replace function public.respawn_cleared_raid_slot(p_cleared_instance_id uuid) returns uuid
language plpgsql security definer set search_path=public as $$
declare v_old public.raid_bosses%rowtype; v_new uuid;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_cleared_instance_id::text||':respawn',0));
 select * into v_old from public.raid_bosses where id=p_cleared_instance_id and status='CLEARED' and respawn_after<=now() for update;
 if not found then return null; end if;
 if exists(select 1 from public.raid_bosses where raid_day_key=v_old.raid_day_key and base_id=v_old.base_id and status='ACTIVE') then return null; end if;
 insert into public.raid_bosses(boss_id,boss_master_id,current_hp,max_hp,base_id,status,spawned_at,expires_at,cycle_id,rotation_date,raid_variant_id,raid_day_key)
 values(v_old.boss_id,v_old.boss_master_id,v_old.max_hp,v_old.max_hp,v_old.base_id,'ACTIVE',now(),v_old.expires_at,gen_random_uuid(),v_old.rotation_date,v_old.raid_variant_id,v_old.raid_day_key) returning id into v_new;
 return v_new;
end $$;

create or replace function public.get_raid_rankings(p_instance_id uuid,p_limit integer default 100,p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=public as $$
declare v_uid uuid:=auth.uid(); v_day text;
begin
 if v_uid is null then raise exception 'authentication required' using errcode='42501'; end if; if p_limit not between 1 and 100 or p_offset not between 0 and 10000 then raise exception 'invalid pagination' using errcode='22023'; end if;
 select raid_day_key into v_day from public.raid_bosses where id=p_instance_id; if v_day is null then raise exception 'Raid day not found' using errcode='P0002'; end if;
 return jsonb_build_object(
 'individual',coalesce((with totals as(select log.user_id,u.username,sum(log.raw_damage)::bigint contribution,min(log.created_at) achieved_at from public.raid_damage_logs log join public.raid_bosses boss on boss.id=log.raid_boss_instance_id and boss.raid_day_key=v_day join public.users u on u.id=log.user_id group by log.user_id,u.username),ranked as(select *,rank()over(order by contribution desc)rank_position from totals)select jsonb_agg(to_jsonb(page)order by contribution desc,achieved_at,user_id)from(select * from ranked order by contribution desc,achieved_at,user_id limit p_limit offset p_offset)page),'[]'::jsonb),
 'guild',coalesce((with totals as(select log.guild_id,g.name guild_name,sum(log.raw_damage)::bigint contribution,min(log.created_at) achieved_at,count(distinct log.user_id)::integer participant_count from public.raid_damage_logs log join public.raid_bosses boss on boss.id=log.raid_boss_instance_id and boss.raid_day_key=v_day join public.guilds g on g.id=log.guild_id where log.guild_id is not null group by log.guild_id,g.name),ranked as(select *,rank()over(order by contribution desc)rank_position from totals)select jsonb_agg(to_jsonb(page)order by contribution desc,achieved_at,guild_id)from(select * from ranked order by contribution desc,achieved_at,guild_id limit p_limit offset p_offset)page),'[]'::jsonb),
 'selfRank',(with totals as(select log.user_id,sum(log.raw_damage)::bigint contribution,min(log.created_at) achieved_at from public.raid_damage_logs log join public.raid_bosses boss on boss.id=log.raid_boss_instance_id and boss.raid_day_key=v_day group by log.user_id),ranked as(select *,rank()over(order by contribution desc)rank_position from totals)select to_jsonb(ranked)from ranked where user_id=v_uid));
end $$;
create or replace function public.get_raid_rankings(p_instance_id uuid) returns jsonb language sql stable security definer set search_path=public as $$ select public.get_raid_rankings(p_instance_id,100,0) $$;

-- Authority / RLS: clients can read master data and their claim receipt, never mutate authority.
alter table public.canonical_master_freeze_versions enable row level security;
alter table public.canonical_quest_enemy_pool_entries enable row level security;
alter table public.canonical_raid_variants enable row level security;
alter table public.canonical_daily_activity_claims enable row level security;
alter table public.raid_clear_reward_claims enable row level security;
alter table public.raid_clear_reward_deliveries enable row level security;
drop policy if exists canonical_master_freeze_read on public.canonical_master_freeze_versions;
create policy canonical_master_freeze_read on public.canonical_master_freeze_versions for select to authenticated using(is_production_enabled);
drop policy if exists canonical_enemy_pool_read on public.canonical_quest_enemy_pool_entries;
create policy canonical_enemy_pool_read on public.canonical_quest_enemy_pool_entries for select to authenticated using(is_production_enabled);
drop policy if exists canonical_raid_variant_read on public.canonical_raid_variants;
create policy canonical_raid_variant_read on public.canonical_raid_variants for select to authenticated using(is_production_enabled);
drop policy if exists raid_clear_claim_owner_read on public.raid_clear_reward_claims;
create policy raid_clear_claim_owner_read on public.raid_clear_reward_claims for select to authenticated using(user_id=auth.uid());
revoke all on public.canonical_master_freeze_versions,public.canonical_quest_enemy_pool_entries,public.canonical_raid_variants,public.canonical_daily_activity_claims,public.raid_clear_reward_claims,public.raid_clear_reward_deliveries from public,anon,authenticated;
grant select on public.canonical_master_freeze_versions,public.canonical_quest_enemy_pool_entries,public.canonical_raid_variants,public.raid_clear_reward_claims to authenticated;
grant all on public.canonical_master_freeze_versions,public.canonical_quest_enemy_pool_entries,public.canonical_raid_variants,public.canonical_daily_activity_claims,public.raid_clear_reward_claims,public.raid_clear_reward_deliveries to service_role;
revoke all on function public.grant_canonical_raid_day_clear_reward(uuid,uuid),public.respawn_cleared_raid_slot(uuid) from public,anon,authenticated;
grant execute on function public.grant_canonical_raid_day_clear_reward(uuid,uuid),public.respawn_cleared_raid_slot(uuid) to service_role;
revoke all on function public.resolve_canonical_reward_item(text) from public,anon,authenticated;
grant execute on function public.resolve_canonical_reward_item(text) to service_role;
revoke all on function public.create_guild_v2(uuid,text,integer) from public,anon;
grant execute on function public.create_guild_v2(uuid,text,integer) to authenticated;

do $$ begin
 if (select count(*) from public.canonical_quest_master where version='2026-08-30' and is_production_enabled)<>21 then raise exception 'Canonical Quest count mismatch'; end if;
 if (select jsonb_array_length(payload->'missions') from public.canonical_master_freeze_versions where domain='MISSION' and version='2026-08-30')<>47 then raise exception 'Canonical Mission count mismatch'; end if;
 if (select count(*) from public.missions where is_enabled)<>40 then raise exception 'Pre-open Mission activation mismatch'; end if;
 if exists(select 1 from public.login_bonus_master where item_id='CASH') then raise exception 'Login Bonus CASH remains'; end if;
 if (select count(*) from public.canonical_raid_variants where version='2026-08-30' and is_production_enabled)<>7 then raise exception 'Canonical Raid variant count mismatch'; end if;
end $$;

notify pgrst,'reload schema';
commit;
